def gen(rng):
    def build(values):
        # insert in the given order into a BST, then serialize in level order
        if not values:
            return 'null'
        if len(values) > 50 and values == sorted(values):
            toks = [str(values[0])]
            for v in values[1:]:
                toks += ['null', str(v)]
            return ' '.join(toks)
        if len(values) > 50 and values == sorted(values, reverse=True):
            toks = [str(values[0])]
            for v in values[1:]:
                toks += [str(v), 'null']
            return ' '.join(toks[:-1])
        val, lc, rc = [values[0]], [-1], [-1]
        for v in values[1:]:
            cur = 0
            while True:
                if v < val[cur]:
                    if lc[cur] == -1:
                        val.append(v); lc.append(-1); rc.append(-1)
                        lc[cur] = len(val) - 1
                        break
                    cur = lc[cur]
                else:
                    if rc[cur] == -1:
                        val.append(v); lc.append(-1); rc.append(-1)
                        rc[cur] = len(val) - 1
                        break
                    cur = rc[cur]
        out = []
        q = [0]
        qi = 0
        while qi < len(q):
            u = q[qi]
            qi += 1
            if u == -1:
                out.append('null')
                continue
            out.append(str(val[u]))
            q.append(lc[u])
            q.append(rc[u])
        while out and out[-1] == 'null':
            out.pop()
        return ' '.join(out)

    def rand_vals(k, lo, hi):
        return rng.sample(range(lo, hi + 1), k)

    tests = [
        build([1]) + '\n' + build([]),
        build([]) + '\n' + build([-5]),
        build([7]) + '\n' + build([7]),
        build([2, 1, 3]) + '\n' + build([2, 1, 3]),
        build([-100000, 100000]) + '\n' + build([100000, -100000]),
        build([4, 2, 6, 1, 3]) + '\n' + build([5, 1, 8, 7, 9]),
        build([1, 2, 3, 4]) + '\n' + build([4, 3, 2, 1]),
    ]
    for _ in range(14):
        a = rng.randint(0, 10)
        b = rng.randint(0, 10)
        if a + b == 0:
            a = 1
        lo, hi = rng.choice([(-20, 20), (-100000, 100000), (0, 30)])
        hi = max(hi, lo + 12)
        tests.append(build(rand_vals(a, lo, hi)) + '\n' + build(rand_vals(b, lo, hi)))
    # large tests
