    tests.append(build(list(range(-100000, -95000))) + '\n' + build(list(range(100000, 95000, -1))))
    tests.append(build(rand_vals(5000, -100000, 100000)) + '\n' + build([]))
    tests.append(build(sorted(rand_vals(5000, -100000, 100000))) + '\n' + build(sorted(rand_vals(5000, -100000, 100000), reverse=True)))
    return tests
